import {expect, it} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

it('logs enum rejection without the supplied identifier', async () => {
  const warnings: string[] = [];
  const record = (category: string, message: string, fields?: Record<string, unknown>) => {
    warnings.push(JSON.stringify({category, message, fields}));
  };
  setLogger({debug: record, info: record, warn: record, error: record});
  try {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'identifier',
        description: 'Select an identifier',
        inputSchema: {type: 'object', properties: {identifier: {enum: ['public']}}},
      },
      async () => 'accepted'
    );

    const response = await registry.execute('identifier', {identifier: 'private-123456789'});

    expect(response.result).toMatch(/identifier.*(enum|allowed)/);
    expect(warnings).toHaveLength(1);
    expect(warnings[0]).toMatch(/identifier/);
    expect(warnings[0]).toMatch(/enum|allowed/);
    expect(JSON.stringify({response, warnings})).not.toContain('private-123456789');
  } finally {
    setLogger();
  }
});
''')
